/* Cinematic field operations. Reuses the existing learning engines and saved work. */
let missionMode='home';
const OP_CHAPTERS=[['01','实地勘测','从一次经历，到可以使用的数据','FIELD EXPEDITION'],['02','预测与判断','让误差推动更好的决策','PREDICTION SYSTEMS'],['03','学习系统','观察参数怎样形成新的能力','LEARNING SYSTEMS'],['04','轨道视觉','用真实影像训练卷积神经网络','ORBITAL VISION'],['05','自主行动','设计目标，探索路径与行动','AUTONOMOUS SYSTEMS'],['06','独立项目','把一个想法变成可检验的模型','BUILD YOUR SYSTEM']];
const NEW_LESSONS={1:['第一次地面探测','作出预测，执行探测，把结果留成记录。'],2:['哪些观测值得记录？','接入新传感器，寻找外观之外的线索。'],3:['你来充当分类器','找出最近的三条经验，用多数票作出判断。'],4:['下一次去哪里采集？','用有限的勘测机会，补齐数据覆盖。'],5:['调查一条错误记录','核实参考答案，修复模型学到的错误。'],16:['建立你的影像档案','选择真实卫星图像，明确输入与参考类别。'],17:['深入一块图像','移动扫描框，看局部像素怎样产生响应。'],18:['训练真正的 CNN','让卷积核和分类层一起从数据中学习。'],19:['寻找视觉系统的弱点','改变图像条件，再用增强训练改善表现。'],20:['审阅新区域的观测','在保留影像上评估，逐张核对并导出模型。'],30:['毕业任务 · 交付你的视觉模型','完成真实图像模型的评估，导出可继续改进的作品。']};
for(let [id,[title,desc]] of Object.entries(NEW_LESSONS))Object.assign(LEVELS[+id-1],{title,desc});
WORLDS.forEach((w,i)=>{w[0]=OP_CHAPTERS[i][1];w[1]=OP_CHAPTERS[i][2]});
// Update application connections to match the revised lessons, retaining source links.
Object.assign(APPLICATIONS[0],{title:'让机器积累可追溯的现场经验',domain:'自主探索',hook:'探索系统需要知道观测从哪里来、行动产生了什么结果。每条记录都应有可核查的来源。',bridge:'你将行动前的观测与行动后的结果配对，形成可用于判断的新证据。',scope:'本关地形与通行结果是教学模拟。真实导航还需要校准的传感器、控制器和安全约束。',visual:'rover',source:'rover',tag:'真实领域 · 原理连接'});
Object.assign(APPLICATIONS[1],{bridge:'你选择在预测前记录哪些传感器信息。遥感和机器人同样需要明确输入的含义。'});
Object.assign(APPLICATIONS[2],{bridge:'你亲自找出最相似的记录并投票。这种方法把已有证据连接到新样本。'});
Object.assign(APPLICATIONS[3],{title:'让采集覆盖陌生条件',domain:'数据采集',hook:'大量重复观测仍可能遗漏重要环境。采集计划决定模型见过哪些情况。',bridge:'你用有限的勘测次数补充经验，并在固定的新地点上比较结果。',scope:'这是数据覆盖的教学实验。真实项目应依据任务分布规划采样，并保留独立评估数据。',visual:'earth',source:'earth',tag:'原理延伸'});
Object.assign(APPLICATIONS[4],{bridge:'你根据原始试验结果修正标签，而不是直接相信模型或附近样本。'});
Object.assign(APPLICATIONS[15],{bridge:'你选取了真实 EuroSAT 图像，把 RGB 像素与原始地表类别标签联系起来。',scope:'本课使用三类、300 张图像的教学子集。图像级划分不能证明跨地区泛化；观测板不提供地理定位。'});
Object.assign(APPLICATIONS[16],{bridge:'你在真实遥感图像上移动 3×3 滤镜，观察局部像素产生的响应。'});
Object.assign(APPLICATIONS[17],{title:'让卷积网络学习地表影像',domain:'地球观测',hook:'机器学习可以帮助处理大量遥感观测，为研究者提供分类与变化分析的线索。',bridge:'你真正更新了卷积核与分类层参数，观察开发集表现和中间特征图。',scope:'本课训练的是 24×24 RGB 小型 CNN，不能直接用于灾害预警或现实地表制图。',visual:'earth',source:'earth',tag:'真实领域 · 原理连接'});
Object.assign(APPLICATIONS[18],{bridge:'你改变光照、位置和方向，检查模型表现，并只对训练样本进行数据增强。'});
Object.assign(APPLICATIONS[19],{title:'把模型表现交给独立证据',domain:'遥感评估',hook:'真实应用需要知道模型在哪些类别上可靠，又在哪里容易出错。',bridge:'你检验了每一类的召回率，审阅错误，并保存了模型与评估记录。',scope:'最终图像不参与梯度更新。看过结果后继续调参会使它成为开发证据，不能再视作全新的独立验收。',visual:'earth',source:'earth',tag:'评估原则'});
function cleanCopy(html){return html.replaceAll('小芽','EV-01').replaceAll('冒险地图','任务中心').replaceAll('训练师学院','FIELD OPERATIONS').replaceAll('击掌！我们做到了。','验证完成。系统获得新能力。').replaceAll('带我做第一步','开始操作').replaceAll('先回地图休息一下','返回任务中心').replaceAll('我来帮它！下一步怎么做？','进入操作，检验你的想法').replaceAll('准备考考EV-01','准备测试模型').replaceAll('轮到你啦','作出判断').replaceAll('小大脑','网络')}
shell=function(content,active='home'){document.getElementById('app').innerHTML=`<div class="ops-shell"><header class="ops-nav"><button class="ops-brand" onclick="navigate('home')"><span class="brand-symbol">A<span>/</span>I</span><span>AI ACADEMY<small>FIELD OPERATIONS</small></span></button><nav aria-label="主导航"><button class="${active==='home'?'active':''}" onclick="navigate('home')">任务中心</button><button class="${active==='lab'?'active':''}" onclick="navigate('lab')">实验室</button><button class="${active==='robot'?'active':''}" onclick="navigate('robot')">设备档案</button></nav><div class="ops-status"><i></i><span>${count()} / 30 已完成</span><button aria-label="切换动画" onclick="toggleMotion()">${motionOn?'动态':'静态'}</button></div></header><main class="ops-main">${cleanCopy(content)}<footer class="ops-footer"><span>AI ACADEMY / FIELD OPERATIONS</span><span>进度与模型保存在本浏览器 · v0.5</span></footer></main></div>`;document.body.classList.toggle('still',!motionOn)};
function missionHeading(id,tag,description){return `<div class="ops-breadcrumb"><button onclick="navigate('home')">← 任务中心</button><span>${tag}</span><b>MISSION ${String(id).padStart(2,'0')}</b></div><div class="mission-heading"><div><span class="eyebrow">${tag}</span><h1>${esc(LEVELS[id-1].title)}</h1><p>${description}</p></div><span class="mission-index">${String(id).padStart(2,'0')}</span></div>`}
function downloadJSON(data,name){let u=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function finishMission(id,detail){progress[id]={date:new Date().toISOString(),result:detail,revision:4};persist('academy-progress-v1',progress);let c=APPLICATIONS[id-1];modal('任务完成 / CAPABILITY VERIFIED',`<div class="mission-success"><span class="eyebrow">MISSION ${String(id).padStart(2,'0')}</span><h2>${LEVELS[id-1].title}</h2><p>${detail}</p><div class="success-application"><span>${c.domain}</span><h3>${c.title}</h3><p>${c.bridge}</p></div><button class="primary wide" onclick="openImpact(${id})">查看这项能力的现实用途 →</button><button class="secondary wide" onclick="closeModal();${id<30?'openLevel('+(id+1)+')':"navigate('lab')"}">${id<30?'直接进入下一任务':'进入实验室'}</button></div>`)}
const savedOpenLevel=openLevel;
openLevel=function(id){stopAnimation();Vision.stop();current=LEVELS[id-1];labMode=false;phase=2;if(id<=5){missionMode='field';Field.open(id)}else if((id>=16&&id<=20)||id===30){missionMode='vision';Vision.open(id)}else{missionMode='legacy';savedOpenLevel(id)}window.scrollTo(0,0)};
const savedNavigate=navigate;navigate=function(p){Vision.stop();missionMode=p;savedNavigate(p)};
const savedOpenLab=openLab;openLab=function(type){Vision.stop();if(type==='cnn'){openLevel(18);return}missionMode='legacy';savedOpenLab(type)};
const savedLoadProject=loadProject;loadProject=function(i){Vision.stop();missionMode='legacy';savedLoadProject(i)};
home=function(){let next=LEVELS.find(l=>!progress[l.id])||LEVELS[0];let ch=OP_CHAPTERS[chapter];shell(`<section class="ops-hero"><div class="hero-overlay"></div><div class="ops-hero-copy"><span class="eyebrow">FIELD OPERATIONS / SEASON 01</span><h1>让机器，<br>学会理解世界。</h1><p>采集真实证据，训练自己的模型。<br>把每一次试验，变成下一步行动的依据。</p><button class="primary" onclick="openLevel(${next.id})">${count()?'继续任务 '+String(next.id).padStart(2,'0'):'启动首次勘测'} <span>→</span></button><button class="hero-link" onclick="openLevel(18)">进入真实 CNN 实验 ↗</button></div><div class="hero-coordinate"><span>EV-01 / EXPLORATION UNIT</span><strong>OBSERVE. LEARN. ACT.</strong><small>机器人与任务场景为艺术设定 · 学习模型真实计算</small></div></section><div class="mission-strip"><div><b>30</b><span>渐进任务</span></div><div><b>300</b><span>真实遥感图像</span></div><div><b>01</b><span>你亲手训练的系统</span></div><button onclick="showImpactGallery()">这些能力能用在哪里？ ↗</button></div><div class="sectionhead ops-sectionhead"><div><span class="eyebrow">YOUR FIELD PROGRAM</span><h2>选择下一次行动</h2></div><span class="muted">随时进入任何任务</span></div><div class="ops-chapters">${OP_CHAPTERS.map((a,i)=>`<button class="${i===chapter?'selected':''}" onclick="chooseChapter(${i})"><small>${a[0]}</small>${a[1]}</button>`).join('')}</div><div class="chapter-intro"><div><span class="eyebrow">${ch[3]}</span><h2>${ch[2]}</h2></div><span>${LEVELS.filter(l=>l.chapter===chapter&&progress[l.id]).length} / 5 完成</span></div><div class="mission-grid">${LEVELS.filter(l=>l.chapter===chapter).map((l,i)=>`<button class="mission-card ${progress[l.id]?'completed':''}" onclick="openLevel(${l.id})"><div class="mission-card-art card-art-${l.chapter}" style="--position:${45+i*8}%"><span>${String(l.id).padStart(2,'0')}</span>${l.chapter===0?`<div class="terrain-photo terrain-${i%4}"></div>`:''}${l.chapter===3?`<img src="assets/eurosat/thumbs/${VISION_POSTERS[i%3]}" alt="真实地表影像" loading="lazy">`:''}</div><div class="mission-card-copy"><small>${progress[l.id]?(NEW_LESSONS[l.id]&&progress[l.id].revision!==4?'旧版进度保留 · 新版待体验':'✓ 已完成 · 可重新实验'):'MISSION '+String(l.id).padStart(2,'0')}</small><h3>${l.title}</h3><p>${l.desc}</p><span>${['现场调查','参数实验','网络实验','视觉任务','策略实验','独立创作'][l.chapter]} <b>↗</b></span></div></button>`).join('')}</div><section class="ops-lab-callout"><div><span class="eyebrow">OPEN LAB</span><h2>带着自己的问题继续实验。</h2><p>比较模型、修改数据、检查失败，并保存可以继续改进的作品。</p></div><button class="secondary" onclick="navigate('lab')">打开实验室 →</button></section>`)};
