const oldLab=lab;lab=function(){oldLab();let app=$('#app');app.innerHTML=app.innerHTML.replace('<div class="labgrid">',`<section class="cnn-lab-callout"><div><span class="eyebrow">REAL IMAGE LEARNING</span><h2>轨道视觉实验室</h2><p>真实遥感图像 · 可学习卷积核 · 逐张审阅 · 模型导出</p></div><button class="primary" onclick="openLab('cnn')">继续我的 CNN 实验 →</button></section><div class="labgrid">`)};
inventory=function(){shell(`<div class="mission-heading"><div><span class="eyebrow">EXPLORATION UNIT / EV-01</span><h1>能力来自完成的实验。</h1><p>保留证据，检验结果，再赋予系统下一项任务。</p></div></div><section class="unit-profile"><div class="unit-portrait"></div><div><span class="eyebrow">SYSTEM CAPABILITIES</span><h2>EV-01 / 探索单元</h2><p>${count()} 项任务完成 · ${projects.length} 个传统实验项目已保存</p><div class="capability-list">${OP_CHAPTERS.map((ch,i)=>{let n=LEVELS.filter(l=>l.chapter===i&&progress[l.id]).length;return `<div><span>${ch[1]}</span><div class="progress"><span style="width:${n*20}%"></span></div><b>${n}/5</b></div>`}).join('')}</div><button class="secondary" onclick="showImpactGallery()">查看现实应用图鉴 →</button></div></section><div class="sectionhead"><h2>独立的实验记录</h2></div><div class="labgrid"><div class="card"><h3>现场勘测档案</h3><p>${Field.saved.records.length} 条观测与结果记录</p><button class="secondary" onclick="downloadJSON(Field.saved,'field-notebook.json')">导出档案 ↓</button></div><div class="card"><h3>视觉模型工作区</h3><p>${Vision.saved.selected.length} 张已选影像 · ${Vision.saved.model?.epochs||0} 轮训练</p><button class="secondary" onclick="openLevel(18)">打开 CNN 工作区 →</button></div></div>`,'robot')};
