Object.assign(APPLICATIONS[29],{title:'把视觉模型交给下一次实验',domain:'独立项目',hook:'一个可以继续改进的作品，需要保留数据定义、模型参数和失败记录。',bridge:'你把真实遥感影像的 CNN、样本编号与评估记录一起导出，形成可追溯的实验。',scope:'本课作品是教学模型，不是部署到真实机器人的导航系统；实际应用还需要完整的数据采集、评估和工程验证。',visual:'earth',source:'earth',tag:'项目方向'});
